output_text:
[
  {
    "id": "must_take_cart_first",
    "text": "At the start of a shopping trip, the shopper is obliged to take the available cart before proceeding with shopping.",
    "abstraction": {
      "state_properties": {
        "atCartBay": "at(1,5)",
        "cartAvailableAtBay": "cartAt(1,5)",
        "shopperHasCart": "hasCart"
      },
      "events": {
        "takeCart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeCart"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they are currently holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "shopperHasCart": "hasCart",
        "noCart": {
          "not": "hasCart"
        }
      },
      "events": {
        "collectItem": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "collectItem",
          "noCart"
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Items may not be carried by hand; shoppers must avoid becoming hand-full and must use a cart instead.",
    "abstraction": {
      "state_properties": {
        "carryingByHand": "handFull",
        "noCart": {
          "not": "hasCart"
        }
      },
      "events": {
        "handPickupWithoutCart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "noCart"
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carryingByHand",
          "handPickupWithoutCart"
        ]
      }
    }
  },
  {
    "id": "return_cart_after_collecting",
    "text": "After placing any item into a cart, the shopper is obliged to return the cart at the courtesy desk before leaving.",
    "abstraction": {
      "state_properties": {
        "atCourtesyDesk": "at(0,1)",
        "cartAtCourtesyDesk": "cartAt(0,1)",
        "shopperHasCart": "hasCart"
      },
      "events": {
        "cartItemPickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "shopperHasCart"
            ]
          },
          "post": null
        },
        "cartReturnAtCourtesyDesk": {
          "pre": {
            "and": [
              "atCourtesyDesk",
              "LEAVE_CART"
            ]
          },
          "post": "cartAtCourtesyDesk"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartItemPickup",
      "discharge": "cartReturnAtCourtesyDesk"
    }
  },
  {
    "id": "cart_drop_only_at_desk",
    "text": "A cart may only be put down at the courtesy-desk cart-return location.",
    "abstraction": {
      "state_properties": {
        "atCourtesyDesk": "at(0,1)"
      },
      "events": {
        "dropCart": {
          "pre": "LEAVE_CART",
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "atCourtesyDesk"
          }
        ]
      }
    }
  },
  {
    "id": "no_carts_in_exit_corridor",
    "text": "Shopping carts are prohibited in the exit corridor, so shoppers must enter that area on foot.",
    "abstraction": {
      "state_properties": {
        "exitCorridor": {
          "or": [
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "shopperHasCart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exitCorridor",
          "shopperHasCart"
        ]
      }
    }
  },
  {
    "id": "proper_exit_after_cart_return",
    "text": "If a shopper takes a cart, they are obliged to exit only after the cart has been parked at the courtesy desk and they are no longer holding it.",
    "abstraction": {
      "state_properties": {
        "cartAtCourtesyDesk": "cartAt(0,1)",
        "withoutCart": {
          "not": "hasCart"
        }
      },
      "events": {
        "takeCart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "properExit": {
          "pre": {
            "and": [
              "EXIT",
              "withoutCart",
              "cartAtCourtesyDesk"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "takeCart",
      "discharge": "properExit"
    }
  },
  {
    "id": "courtesy_interaction_is_cart_return",
    "text": "The only permitted interaction at the courtesy desk is leaving the cart there.",
    "abstraction": {
      "state_properties": {
        "atCourtesyDesk": "at(0,1)",
        "cartAtCourtesyDesk": "cartAt(0,1)"
      },
      "events": {
        "courtesyInteraction": {
          "pre": {
            "and": [
              "atCourtesyDesk",
              "INTERACT"
            ]
          },
          "post": null
        },
        "courtesyCartDrop": {
          "pre": {
            "and": [
              "atCourtesyDesk",
              "LEAVE_CART"
            ]
          },
          "post": "cartAtCourtesyDesk"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "courtesyInteraction",
          {
            "not": "LEAVE_CART"
          }
        ]
      }
    }
  }
]
